export const authPlugin = new Elysia({ name: "auth-plugin" }).resolve(
    { as: "scoped" },
    async ({ status, request: { headers } }) => {
        const session = await auth.api.getSession({ headers });
        if (!session) return status(401);
        return {
            user: session.user,
            session: session.session,
        };
    },
);
```

It creates a scoped Elysia plugin that resolves the current session from request headers, returns a 401 if no session exists, and otherwise injects `user` and `session` into the request context.

